import json
import base64

batch = []

# Song settings
batch.append({"name": "song_set", "arguments": {"bpm": 145, "speed": 5, "loop_start": 0, "channels": 8, "name": "Keygen Dreams"}})

# Read base64 files
samples = [
    (1, "Kick"),
    (2, "Snare"),
    (3, "HiHat"),
    (4, "Bass"),
    (5, "Lead"),
    (6, "Pad"),
    (7, "Pluck"),
    (8, "Chord"),
]

for inst, name in samples:
    with open(f"/workspace/{name.lower()}.b64", "r") as f:
        b64 = f.read().strip()
    batch.append({
        "name": "sample_create_from_pcm",
        "arguments": {
            "instrument": inst,
            "sample": 0,
            "pcm": b64,
            "encoding": "float32",
            "name": name
        }
    })
    # Set loop for tonal instruments
    if name in ["Bass", "Lead", "Pad"]:
        batch.append({
            "name": "sample_set",
            "arguments": {
                "instrument": inst,
                "sample": 0,
                "loop_start": 0,
                "loop_length": -1,  # full sample loop
                "volume": 64,
                "relative_note": 0
            }
        })
    else:
        batch.append({
            "name": "sample_set",
            "arguments": {
                "instrument": inst,
                "sample": 0,
                "volume": 64,
                "relative_note": 0
            }
        })
    batch.append({
        "name": "instrument_set",
        "arguments": {
            "instrument": inst,
            "name": name
        }
    })

with open("/workspace/setup_batch.json", "w") as f:
    json.dump(batch, f)

print("Batch JSON written")
EOF
python3 /workspace/setup_module.py"}

